INSERT INTO ticket_history (ticket_record_id, field, old_value, new_value, changed_by, changed_at, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06FB0TGPVX68TB56C230B934J8', 'description', NULL, 'Zero matches now exits 0 with an empty [] instead of exit 2 (NoMatch), which is retired. The empty result lives in the data, never the exit code, so callers treating non-zero as failure stop flagging empty results as errors. Shipped in commit ef73d6e: internal/diag drops NoMatch, all subcommands return success on empty, docs/SKILL/CLAUDE updated, integration tests flipped to exit 0.', NULL, '2026-05-25 09:42:17', '2026-05-25 09:42:17', '2026-05-25 09:42:17', NULL, '89792c3b2453b1fd754fd7ffe1adb429', 2) ON CONFLICT(hash) DO NOTHING;
